// `new Item(id, name, slot, zone, level, props)` — mirrors ItemAux.Item: the
// stored value is base * (1 + level/100) and `base` keeps the raw datamined number.
export class Item {
  constructor(id, name, slot, zone, level, props) {
    this.id = id; this.name = name; this.slot = slot; this.zone = zone; this.level = level;
    this.statnames = []; this.base = {}; this.disable = false;
    for (const p of props) {
      this.statnames.push(p[0]);
      this[p[0]] = p[1] * (1 + level / 100);
      this.base[p[0]] = p[1];
    }
  }
}
export class EmptySlot extends Item {
  constructor(slot) {
    super("", slot ? "Empty " + slot[0][0].toUpperCase() + slot[0].substring(1) + " Slot" : "Empty Slot",
      slot, SetName.SAFE, 100, []);
    this.empty = true;
  }
}

