/* ---------------- deterministic helpers ---------------- */
export function parseNum(s) {
  if (typeof s === "number") return s;
  if (s === undefined || s === null) return NaN;
  const t = String(s).trim().replace(/,/g, "");
  if (t === "") return NaN;
  return Number(t);
}

export function fmtNumber(n) {
  if (typeof n !== "number") return String(n);
  if (!Number.isFinite(n)) return String(n);
  if (Number.isInteger(n) && Math.abs(n) < 1e15) return String(n);
  return String(n);
}

export function csvCell(v) {
  const s = v === undefined || v === null ? "" : String(v);
  return /[",\n\r]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
}

export function writeCsv(rows, columns) {
  return (
    [columns.join(",")]
      .concat(rows.map((r) => columns.map((c) => csvCell(r[c])).join(",")))
      .join("\n") + "\n"
  );
}

export function round(x, d) {
  const f = Math.pow(10, d);
  return Math.round(x * f) / f;
}

// Relative closeness used to compare transcribed (rounded) values to formula values.
export function closeTo(a, b, tol = 0.01) {
  if (!Number.isFinite(a) || !Number.isFinite(b)) return false;
  if (b === 0) return a === 0;
  return Math.abs(a - b) / Math.abs(b) <= tol;
}

// Evaluate the only arithmetic the Boss_Fights page uses: `BASE*MULT^POW` or a
// plain number (`13e5`, `4`). No eval(), no clock, no randomness.
export function evalBossExpr(expr) {
  const e = String(expr).trim().replace(/\s/g, "");
  const m = e.match(/^([0-9.]+e?[0-9]*)\*([0-9.]+)\^([0-9.]+)$/i);
  if (m) return parseNum(m[1]) * Math.pow(parseNum(m[2]), parseNum(m[3]));
  return parseNum(e);
}

/* ---------------- local cache readers ---------------- */
export function readRef(name) {
  return readFileSync(resolve(REF_DIR, name), "utf8");
}

export function readRefJson(name) {
  return JSON.parse(readRef(name));
}
